package com.campus.tracker.export;

import java.io.IOException;
import java.io.InputStream;
import java.nio.file.Path;

/** Keys are generated by the server; storage has no public routes or signed URLs. */
public interface ExportObjectStore {
    void put(String key, Path file) throws IOException;
    InputStream open(String key) throws IOException;
    void delete(String key) throws IOException;
    static void validateKey(String key) {
        if (key == null || !key.matches("jobs/[a-f0-9-]{36}/[a-f0-9-]{36}\\.csv")) throw new IllegalArgumentException("Invalid export object key");
    }
}
